def close_duplicate_attempts(apps, schema_editor):
    """Deja un solo intento abierto por persona y evaluación (el más reciente) antes de crear la restricción."""
    Attempt = apps.get_model('hub', 'Attempt')
    seen = set()
    for attempt in Attempt.objects.filter(finished=False).order_by('-started', '-pk'):
        key = (attempt.user_id, attempt.assessment_id)
        if key in seen:
            attempt.finished = True
            attempt.finished_at = attempt.updated
            attempt.save(update_fields=['finished', 'finished_at'])
        seen.add(key)


def assign_landing(apps, schema_editor):
    Resource = apps.get_model('hub', 'Resource')
    for title, landing in LANDING_BY_TITLE.items():
        Resource.objects.filter(title=title).update(landing=landing)


